import{_ as a,o as n,c as t,a0 as i}from"./chunks/framework.DhQjJcnt.js";const p=JSON.parse('{"title":"Skill: /update-spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/update-spec.md","filePath":"references/skills/update-spec.md"}'),o={name:"references/skills/update-spec.md"};function c(l,e,d,s,r,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="skill-update-spec" tabindex="-1">Skill: <code>/update-spec</code> <a class="header-anchor" href="#skill-update-spec" aria-label="Permalink to &quot;Skill: `/update-spec`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>update-spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/update-spec &lt;bundle-id&gt;</code></li><li>Dùng để vá/cập nhật nhỏ (delta update) trên một Spec đã tồn tại, thay vì viết mới toàn bộ.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li><code>ir/design.yaml</code> (nếu liên quan tới giao diện, tech).</li><li><code>ir/spec.yaml</code> (nếu liên quan tới nội dung chữ / acceptance).</li><li>File bundle gốc <code>*.bundle.yaml</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File <code>*.bundle.yaml</code> được patch (sửa đổi) cục bộ.</li><li>Gắn thêm tag <code>#update:*</code> và tăng <code>specRevision</code>.</li><li>Đổi trạng thái <code>featureStatus</code> từ <code>wire</code> sang <code>need-update</code> nếu cần.</li><li>Chạy <code>flowgrid split</code> và kiểm tra tính toàn vẹn thành công.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Cập nhật <strong>cục bộ (Delta Update)</strong>: Dùng khi có thay đổi nhỏ (một kịch bản, 1 khối UI, 1 trường API) trên hệ thống hiện hành. Không dùng để viết lại toàn bộ từ đầu (full rewrite).</li><li>Bảo toàn dữ liệu: Nghiêm cấm xóa các dấu vết legacy (legacy evidence) hay các khối dữ liệu không liên quan trong lúc cập nhật.</li><li>Bảo toàn Ma trận lỗi: Khi sửa action hoặc endpoint, bắt buộc phải giữ và cập nhật ma trận xử lý lỗi UI (<code>onSuccess</code>, <code>onCommonError</code>, <code>onSpecificError</code>) và API Hashtags (<code>#err:*</code>).</li><li>Không tự ý thêm nhãn <code>codegen</code> hoặc <code>gen:</code> mà không có sự xác nhận của Dev (phải chuyển giao sang <code>/grill-dev</code>).</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận feedback/issue cần thay đổi nhỏ (từ <code>qa-resolve</code> hoặc thay đổi requirement mới).</li><li><strong>Sau đó:</strong> Tuỳ thuộc vào thành phần cập nhật, có thể phải gọi <code>/grill-bqa</code> (nếu sửa UX/copy) hoặc <code>/grill-dev</code> (nếu sửa tech/API), rồi mới tới <code>/prototype</code>.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Luật AskQuestion Tech Debt:</strong> Nếu thông tin cập nhật bị hổng (gap), phải dùng AskQuestion Form. Bắt buộc có option <code>&quot;Log as Tech Debt&quot;</code>. Nếu user chọn, ghi nợ vào <code>qa/open/</code> (<code>qa-inbox.md</code>), tuyệt đối không tự chế (invent) business data.</li><li>Không đọc và viết vào thẳng các file <code>*.md</code> hay sửa trực tiếp thư mục <code>ir/</code>. Phải sửa <code>bundle.yaml</code> rồi split.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/update-spec</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const g=a(o,[["render",c]]);export{p as __pageData,g as default};
